<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Rental;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class RentalStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\RentalModel',
  1 => 'App\\Controllers\\RentalController',
  2 => 'App\\Validation\\RentalRules',
  3 => 'App\\Entities\\RentalEntity',
  4 => 'App\\Services\\RentalService',
  5 => 'App\\Controllers\\Api\\V1\\RentalApiController',
  6 => 'App\\API\\Resources\\RentalResource',
  7 => 'App\\Validation\\RentalApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
